 slates=[("2025-10-07","small/season-opening",3,22,"odds_latest_compatible.json"),("2026-01-26","medium/identity",4,44,"odds_latest_compatible.json"),("2026-03-14","full slate",19,146,"odds_latest.json")]
 write_csv(f"nhl_hostile_replay_slate_inventory_{DATE}.csv",[{"slate_date":d,"selection_reason":r,"provider_events":e,"bookmaker_blocks":b,"frozen_before_testing":"YES","performance_selected":"NO","archive":a} for d,r,e,b,a in slates])
 write_csv(f"nhl_historical_replay_fidelity_audit_{DATE}.csv",[{"slate_date":d,"MIDDAY":"BOUNDED_RECONSTRUCTION","FINAL_PREGAME":"BOUNDED_RECONSTRUCTION","raw_payload_parsing":"EXACT_HISTORICAL_STATE","outcome_use":"grading plumbing only","limitation":"date archive does not prove exact intraday state"} for d,*_ in slates])
 groups={"A_SCHEDULE":["duplicate game ID","missing game ID","changed start time","rescheduled game","postponed game","cancelled game","home/away reversal","unknown game type","incorrect canonical season","franchise rename","wrong provider game binding"],"B_TIMING":["quote timestamp missing","capture after puck drop","provider prestart/capture poststart","stale quote","clock disagreement","duplicate timestamp","start changed after capture"],"C_MAINLINE":["missing prior game","duplicated prior game","future game included","malformed rest","season reset failure","missing schedule chain","feature order mutation","parameter hash mismatch"],"D_SOG":["missing player","duplicate player","ambiguous player","missing rate","missing TOI","fallback failure","wrong line","unsupported side","prediction collision","game-player mismatch"],"E_MARKET":["no market","partial books","missing side","conflicting lines","suspended","malformed price","invalid book","delayed market","market ID change","event ID change","stale payload","ambiguous player quote"],"F_POLICY":["missing config","config hash mismatch","unpersisted override","rule reorder","cap mid-run","duplicate suppression","rank tie","manual action unledgered","upload no candidate","wrong quote snapshot"],"G_ARCHIVE":["directory collision","partial write","manifest missing","manifest mismatch","raw hash mismatch","interrupted run","rerun after failure","stale intermediate","grade before final","grading mutation"],"H_CROSS_LANE":["concurrent same slate","one lane fails","schedule refreshed between lanes","identity changes between captures","namespace collision","wrong-lane market","shared utility failure"]}
