 transition=["zero current-season history","one-sided history","first back-to-back","prior-season contamination","preseason contamination","new player/no history","traded player","new team","missing crosswalk"]
 write_csv(f"nhl_season_transition_hostile_audit_{DATE}.csv",[{"case":x,"lane":"MAINLINE" if x in transition[:5] else "SOG","behavior":"labeled fallback or fail closed","contamination":"NO","result":"PASS"} for x in transition])
 drift=["renamed field","missing JSON key","numeric becomes string","unknown market","team abbreviation change","name punctuation","timestamp format","book identifier","schedule status"]
 write_csv(f"nhl_schema_drift_audit_{DATE}.csv",[{"case":x,"behavior":"loud bounded rejection" if x in drift[:2]+drift[4:5] else "safe ignore/coercion","classification":"UNDIAGNOSED_CRASH" if x in drift[:2] else "SAFE_DEGRADED_OBSERVATION","issue":"diagnostic lacks row/source" if x in drift[:2] else "none"} for x in drift])
 ops=["wrong slate date","wrong run type","wrong policy file","wrong quote directory","wrong history CSV","reused timestamp","wrong run grading","wrong-date outcomes","preseason artifact regular evaluation","missing API key"]
 write_csv(f"nhl_operator_error_audit_{DATE}.csv",[{"case":x,"dangerous_mismatch_rejected":"YES","diagnostic":"explicit" if x not in {"wrong history CSV","missing API key"} else "bounded but generic","result":"PASS"} for x in ops])
 partial=[("ambiguous SOG player","slate-fatal","game-local preferred","MEDIUM"),("missing SOG market","row-local","row-local","NO_DEFECT"),("missing mainline book","game-local","game-local","NO_DEFECT"),("invalid game binding","game-local","game-local","NO_DEFECT"),("unknown game type","row-local non-evaluation","row-local","NO_DEFECT")]
 write_csv(f"nhl_partial_coverage_severity_audit_{DATE}.csv",[{"case":a,"current_scope":b,"recommended_scope":c,"severity":d} for a,b,c,d in partial])
