 defects=[
 ("D01","CRITICAL","TIMING","SOG accepted quote capture later than declared run","REMEDIATED"),("D02","CRITICAL","IDENTITY","SOG player inputs not bound to canonical game spine","REMEDIATED"),("D03","HIGH","GRADING","SOG outcomes lacked season/slate binding","REMEDIATED"),("D04","HIGH","IDENTITY","mainline schedule slate did not bind CLI slate","REMEDIATED"),("D05","HIGH","GRADING","mainline outcomes lacked slate binding","REMEDIATED"),("D06","CRITICAL","MODEL_BINDING","frozen scorer/champion bytes not pinned at runtime","REMEDIATED"),("D07","MEDIUM","RECOVERY","direct writes need manual cleanup after interruption","OPEN"),("D08","MEDIUM","OBSERVABILITY","schema failures lack row/source diagnostics","OPEN"),("D09","MEDIUM","OPERATOR_SAFETY","one player-spine error blocks whole SOG slate","OPEN")]
 write_csv(f"nhl_hostile_defect_registry_{DATE}.csv",[{"defect_id":a,"severity":b,"type":c,"finding":d,"status":e,"action":"FIX_BEFORE_PRESEASON" if b in {"CRITICAL","HIGH"} else "FIX_BEFORE_REGULAR_SEASON"} for a,b,c,d,e in defects])
